    await tx.execute(sql`set transaction isolation level repeatable read`)
    await lockedActor(tx, actor)
    const partners = await rows(tx, sql`select p.id,u.display_name,coalesce((select sum(l.amount_pence) from expansion_commission_ledger l where l.partner_id=p.id),0)::text as earned_pence,coalesce((select sum(b.amount_pence) from expansion_payouts b where b.p
    const payments = await rows(tx, sql`select e.id,e.contract_id,e.reference,e.milestone,e.net_pence::text,e.gross_pence::text,e.reverses_event_id,e.refund_treatment,e.calculated_adjustment_pence::text,e.created_at,p.invoice_id,i.client_name_snapshot as clien
      exists(select 1 from commercial_audit a where a.entity='partner_finance' and a.record_id=e.id::text and a.action='refund_entitlement_retained') as review_resolved
      from expansion_payment_events e left join commercial_payments p on p.id=e.commercial_payment_id left join invoices i on i.id=p.invoice_id order by e.created_at desc,e.id`)
    const payouts = await rows(tx, sql`select id,partner_id,amount_pence::text,invoice_reference,case when c.payout_id is not null then 'cancelled' else p.status end as status,created_at,approved_at,paid_at,settlement_reference,c.cancelled_at,c.reason as cance
    return { partners, payments, payouts }
  })
}


