.sc-button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;padding:8px 16px;border-radius:6px;border:1px solid #cfb578;background:#cfb578;color:#161616;font:inherit;font-size:12px;font-weight:650;text-decoration:none;cursor:pointer}
